Write a small test that matches your access pattern. Here’s a skeleton:

```cpp
#include <vector>
#include <cstdint>
#include <chrono>
#include <iostream>

struct alignas(64) SmallObject {  // 64 bytes to fill a cache line
    int data[16];
};

// Custom pool: bump allocator, no free list
class BumpPool {
    char* mem;
    size_t used;
    size_t capacity;
public:
    BumpPool(size_t max_objects) : capacity(max_objects * sizeof(SmallObject)) {
        mem = (char*)std::aligned_alloc(64, capacity);
        used = 0;
    }
    ~BumpPool() { std::free(mem); }
    void* allocate() {
        if (used + sizeof(SmallObject) > capacity) throw std::bad_alloc();
        void* ptr = mem + used;
        used += sizeof(SmallObject);
        return ptr;
    }
    void reset() { used = 0; }
};

int main() {
    constexpr size_t N = 1'000'000;

    // ---- Vector ----
    std::vector<SmallObject> vec;
    vec.reserve(N);
    for (size_t i = 0; i < N; ++i) vec.emplace_back();

    auto start = std::chrono::high_resolution_clock::now();
    volatile int sum = 0;
    for (auto& obj : vec) {
        sum += obj.data[0];
    }
    auto end = std::chrono::high_resolution_clock::now();
    std::cout << "Vector traversal: " << (end - start).count() << " ns\n";

    // ---- Pool ----
    BumpPool pool(N);
    SmallObject* objs = (SmallObject*)pool.allocate(); // allocate all at once
    // (You'd normally allocate one by one, but for linear access we can pre-alloc)

    start = std::chrono::high_resolution_clock::now();
    sum = 0;
    for (size_t i = 0; i < N; ++i) {
        sum += objs[i].data[0];
    }
    end = std::chrono::high_resolution_clock::now();
    std::cout << "Pool traversal: " << (end - start).count() << " ns\n";

    return 0;
}
```

Run with `perf stat -e cache-misses,L1-dcache-load-misses` to see real numbers.

