#include <vector>
#include <memory_resource>
#include <cstdlib>

struct alignas(32) SmallObject { int data[8]; };

// Benchmark: iterate over 100k objects stored in vector vs. bump pool
static void BM_VectorIteration(benchmark::State& state) {
    const size_t N = state.range(0);
    std::vector<SmallObject> vec(N);
    for (auto& s : vec) s.data[0] = 1; // touch once

    for (auto _ : state) {
        int sum = 0;
        for (const auto& s : vec) sum += s.data[0];
        benchmark::DoNotOptimize(sum);
    }
}

static void BM_BumpPoolIteration(benchmark::State& state) {
    const size_t N = state.range(0);
    auto* pool = std::pmr::monotonic_buffer_resource(N * sizeof(SmallObject));
    std::pmr::vector<SmallObject> vec(N, &pool); // uses pool

    for (auto _ : state) {
        int sum = 0;
        for (const auto& s : vec) sum += s.data[0];
        benchmark::DoNotOptimize(sum);
    }
}

BENCHMARK(BM_VectorIteration)->Arg(1<<20);
BENCHMARK(BM_BumpPoolIteration)->Arg(1<<20);
